import numpy as np, warnings; warnings.filterwarnings('ignore')
from sklearn.ensemble import ExtraTreesRegressor, GradientBoostingRegressor, RandomForestRegressor
from scipy.stats import norm
d=np.load('feats.npz'); X=np.nan_to_num(d['Xt']); yt=d['yt']; yb=d['yb']
ls=np.log10(yt)
def fitpred(Xa,ya,Xb):
    ps=[]
    for M in [ExtraTreesRegressor(500,random_state=0),GradientBoostingRegressor(random_state=0,n_estimators=300,max_depth=3,learning_rate=0.05,subsample=0.8),RandomForestRegressor(500,random_state=0)]:
        M.fit(Xa,ya); ps.append(M.predict(Xb))
    return np.mean(ps,axis=0)
rng=np.random.default_rng(1)
variants={}
for sd in [0.3,0.4,0.5,0.7]: variants[f'prob{sd}']=('prob',sd)
for th in [3.0,3.1,3.2,3.4,3.6]: variants[f'hard{th}']=('hard',th)
res={k:[] for k in variants}
for trial in range(15):
    idx=rng.permutation(len(X)); te=idx[:100]; tr=idx[100:]
    ps=fitpred(X[tr],ls[tr],X[te]); pg=fitpred(X[tr],yb[tr],X[te]); shg=10**ps
    for name,(kind,p) in variants.items():
        if kind=='prob': score=shg*(1-norm.cdf(3.0,loc=pg,scale=p))
        else: score=shg*(pg>=p)
        top=np.argsort(-score)[:5]
        res[name].append(np.where(yb[te][top]>=3, yt[te][top],0.0).mean())
for k in variants: print(f'{k:10s} {np.mean(res[k]):.2f}')
