def clf(Xa,ca,Xb):
    return np.mean([M.fit(Xa,ca).predict_proba(Xb)[:,1] for M in [ExtraTreesClassifier(400,random_state=0),GradientBoostingClassifier(random_state=0,n_estimators=300,max_depth=3,learning_rate=0.05),RandomForestClassifier(400,random_state=0)]],axis=0)
