import numpy as np, csv, warnings; warnings.filterwarnings('ignore')
from sklearn.ensemble import *
from pymatgen.core import Structure
d=np.load('feats2.npz'); X=d['Xt']; Xp=d['Xp']; yt=d['yt']; yb=d['yb']; ls=np.log10(yt)
c=(yb>=3).astype(int)
def reg(y,seeds=range(6)):
    P=[]
    for s in seeds:
        for M in [ExtraTreesRegressor(600,random_state=s),GradientBoostingRegressor(random_state=s,n_estimators=400,max_depth=3,learning_rate=0.05,subsample=0.8),RandomForestRegressor(600,random_state=s)]:
            P.append(M.fit(X,y).predict(Xp))
    return np.mean(P,0)
def cl(seeds=range(6)):
    P=[]
    for s in seeds:
        for M in [ExtraTreesClassifier(600,random_state=s),GradientBoostingClassifier(random_state=s,n_estimators=400,max_depth=3,learning_rate=0.05),RandomForestClassifier(600,random_state=s)]:
            P.append(M.fit(X,c).predict_proba(Xp)[:,1])
    return np.mean(P,0)
shg=10**reg(ls); pg=reg(yb); pc=cl()
po=list(csv.DictReader(open('nlo_pool.csv')))
rows=[]
for i,r in enumerate(po):
    s=Structure.from_str(r['poscar'],fmt='poscar')
    rows.append((shg[i]*pc[i]**2, r['candidate_id'], s.composition.reduced_formula, shg[i], pg[i], pc[i]))
rows.sort(reverse=True)
print("id    formula           score    shg   gap  P(>=3)")
for sc,cid,f,sh,g,p in rows[:22]:
    print(f'{cid} {f:18s} {sc:7.2f} {sh:7.2f} {g:5.2f} {p:5.2f}')
